<script lang="ts">
  import { onMount } from "svelte";
  import { goto } from "$app/navigation";
  import { api, type Ticket } from "$lib/api";
  import MetricCard from "$lib/components/MetricCard.svelte";
  import PriorityChip from "$lib/components/PriorityChip.svelte";
  import SlaIndicator from "$lib/components/SlaIndicator.svelte";

  type Kpi = { totalTickets:number; openTickets:number; avgFirstResponseMinutes:number|null; avgResolutionMinutes:number|null; slaCompliancePercent:number|null; avgRating:number|null; byCategory:{name:string;count:number}[]; monthly:{month:string;count:number}[]; perAgent:{agentId:string;name:string;tickets:number;resolved:number;avgResolutionMinutes:number|null}[] };
  let kpi: Kpi | null = null; let tickets: Ticket[] = []; let month = ""; let message = ""; let loading = false;
  const months = Array.from({ length: 12 }, (_, index) => { const date = new Date(new Date().getFullYear(), new Date().getMonth() - index, 1); return { value:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}`, label:new Intl.DateTimeFormat("id-ID",{month:"long",year:"numeric"}).format(date) }; });
  const formatDuration = (minutes:number|null) => { if (minutes === null) return "—"; const rounded=Math.round(minutes); return rounded < 60 ? `${rounded} mnt` : `${Math.floor(rounded/60)}j ${rounded%60}mnt`; };
  const formatMonth = (key:string) => new Intl.DateTimeFormat("id-ID",{month:"short"}).format(new Date(`${key}-01`));
  const isRisk = (ticket:Ticket) => ticket.slaResolutionBreached || (!!ticket.slaResolutionDueAt && !ticket.resolvedAt && Date.parse(ticket.slaResolutionDueAt)-Date.now() <= 7_200_000);
  async function load() { loading = true; message = ""; const params=new URLSearchParams(); if(month){ const [year, monthNumber]=month.split("-").map(Number); params.set("from",new Date(year,monthNumber-1,1).toISOString()); params.set("to",new Date(year,monthNumber,0,23,59,59).toISOString()); } const query=params.toString(); try { const [overview, ticketData]=await Promise.all([api<Kpi>(`/kpi/overview${query?`?${query}`:""}`),api<Ticket[]>("/tickets")]); kpi=overview; tickets=ticketData; } finally { loading = false; } }
  onMount(() => { load().catch(cause=>message=cause instanceof Error?cause.message:"Data dashboard gagal dimuat"); });
  $: attention = tickets.filter(ticket => isRisk(ticket) || ticket.priority === "URGENT").slice(0,4);
  $: maxMonthly = Math.max(1,...(kpi?.monthly.map(item=>item.count) ?? [1]));
</script>

<svelte:head><title>Command Center — Ticket.Ops</title></svelte:head>

<section class="dashboard">
  <header class="section-header"><div><h1>Good morning, team.</h1><p class="section-desc">Pantau kualitas layanan, risiko SLA, dan pekerjaan yang membutuhkan tindak lanjut sekarang.</p></div><label class="period"><span>Periode</span><select bind:value={month} disabled={loading} aria-busy={loading} on:change={() => load().catch(cause => message=cause instanceof Error?cause.message:"Gagal memuat KPI")}><option value="">Semua periode</option>{#each months as option}<option value={option.value}>{option.label}</option>{/each}</select></label></header>
  {#if !kpi}<div class="dashboard-loading" aria-live="polite"><span aria-hidden="true"></span><p>{message || "Menyiapkan command center…"}</p>{#if message}<button class="ghost" disabled={loading} on:click={() => load().catch(cause => message=cause instanceof Error?cause.message:"Gagal memuat KPI")}>Coba lagi</button>{/if}</div>{:else}
    {#if message}<p class="inline-message" role="status">{message}</p>{/if}
    <div class="metrics reveal"><MetricCard label="Tiket aktif" value={kpi.openTickets} detail={`${kpi.totalTickets} tiket pada periode ini`} /><MetricCard label="Risiko SLA" value={attention.length} detail="Butuh perhatian segera" tone="risk" /><MetricCard label="Respons pertama" value={formatDuration(kpi.avgFirstResponseMinutes)} detail="Rata-rata waktu respons" /><MetricCard label="Kepatuhan SLA" value={kpi.slaCompliancePercent === null ? "—" : `${kpi.slaCompliancePercent}%`} detail="Dari tiket yang diselesaikan" /><MetricCard label="Kepuasan pengguna" value={kpi.avgRating === null ? "—" : `${kpi.avgRating.toFixed(1)} / 5`} detail="Rating tiket selesai" /><MetricCard label="AI knowledge assist" value="Ready" detail="Draft selalu ditinjau agen" tone="ai" /></div>
    <div class="work-grid">
      <article class="attention panel"><div class="panel-head"><div><h2>Prioritas hari ini</h2></div><a class="text-action" href="/tickets">Lihat semua<svg aria-hidden="true" viewBox="0 0 16 16"><path d="M3 8h9M8.5 4.5 12 8l-3.5 3.5"/></svg></a></div>
      {#if attention.length === 0}<div class="empty-state"><strong>Tidak ada risiko SLA saat ini</strong>Antrean tampak sehat. Pantau kembali saat tiket baru masuk.</div>{:else}<div class="attention-list">{#each attention as ticket}<button class="attention-row" on:click={() => goto(`/tickets/${ticket.id}`)}><div class="ticket-main"><span class="ticket-code">{ticket.code}</span><strong>{ticket.title}</strong><small>{ticket.user.name} · {ticket.category.name}</small></div><div class="ticket-tags"><PriorityChip priority={ticket.priority}/><SlaIndicator dueAt={ticket.slaResolutionDueAt} breached={ticket.slaResolutionBreached ?? false} resolved={!!ticket.resolvedAt}/></div></button>{/each}</div>{/if}</article>
      <article class="ai-brief"><div><h2>Konteks AI, keputusan agen.</h2><p>AI membantu merangkum keluhan dan menyarankan artikel knowledge base yang relevan. Agen tetap memegang keputusan, balasan, dan perubahan status.</p><a href="/knowledge">Kelola knowledge base</a></div><svg class="ai-marker" aria-hidden="true" viewBox="0 0 24 24"><path d="m12 3 .9 5.1L18 9l-5.1.9L12 15l-.9-5.1L6 9l5.1-.9L12 3Z"/><path d="m18.5 15 .45 2.05L21 17.5l-2.05.45L18.5 20l-.45-2.05L16 17.5l2.05-.45.45-2.05Z"/></svg></article>
    </div>
    <div class="analytics">
      <article class="panel chart-panel"><div class="panel-head"><div><h2>Tren enam bulan</h2></div></div><div class="bar-chart" aria-label="Grafik volume tiket enam bulan terakhir">{#each kpi.monthly as item}<div class="bar"><span class="bar-value">{item.count}</span><div class="track"><i style={`height:${Math.max(4,item.count/maxMonthly*100)}%`}></i></div><small>{formatMonth(item.month)}</small></div>{/each}</div></article>
      <article class="panel category-panel"><h2>Permintaan terbanyak</h2>{#if kpi.byCategory.length === 0}<p class="empty-copy">Belum ada data kategori.</p>{:else}<div class="category-list">{#each kpi.byCategory.slice(0,5) as item}<div><span>{item.name}</span><div class="category-line"><i style={`width:${item.count/Math.max(1,kpi.byCategory[0].count)*100}%`}></i></div><b>{item.count}</b></div>{/each}</div>{/if}</article>
    </div>
    <article class="panel agents"><div class="panel-head"><div><h2>Distribusi penyelesaian</h2></div></div>{#if kpi.perAgent.length === 0}<p class="empty-state">Belum ada data agen.</p>{:else}<div class="table-scroll"><table><thead><tr><th>Agen</th><th>Ditangani</th><th>Selesai</th><th>Rata-rata resolusi</th><th>Progress</th></tr></thead><tbody>{#each kpi.perAgent as agent}<tr><td><strong>{agent.name}</strong></td><td>{agent.tickets}</td><td>{agent.resolved}</td><td>{formatDuration(agent.avgResolutionMinutes)}</td><td><div class="progress"><i style={`width:${agent.tickets ? agent.resolved/agent.tickets*100 : 0}%`}></i></div></td></tr>{/each}</tbody></table></div>{/if}</article>
  {/if}
</section>

<style>
  .section-header { display:flex; justify-content:space-between; align-items:flex-end; gap:1.5rem; }.section-header h1 { margin:0 0 .6rem; font-size:clamp(1.8rem,4vw,2.7rem); }.section-desc { max-width:620px; margin:0; color:var(--dim); font-size:.84rem; line-height:1.55; }.period { display:grid; gap:.35rem; min-width:180px; color:var(--dim); font-size:.68rem; font-weight:700; }.period select { padding:.65rem .75rem; font-size:.76rem; }.period select:disabled { cursor:wait; opacity:.72; }.dashboard-loading { display:grid; place-items:center; gap:.85rem; min-height:320px; color:var(--dim); text-align:center; }.dashboard-loading > span { width:1.4rem; height:1.4rem; border:2px solid var(--line); border-top-color:var(--acid); border-radius:50%; animation:spin .75s linear infinite; }.dashboard-loading p { margin:0; font-size:.8rem; }.dashboard-loading button { padding:.65rem .85rem; font-size:.72rem; }.inline-message { margin:1rem 0 0; color:var(--alert); font-size:.76rem; }.metrics { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:1rem; margin-top:2rem; }.work-grid { display:grid; grid-template-columns:1.55fr 1fr; gap:1rem; margin-top:1rem; }.attention { overflow:hidden; }.panel-head { display:flex; justify-content:space-between; align-items:flex-start; gap:1rem; padding:1.15rem 1.2rem; }.panel-head h2,.category-panel h2 { margin:0; font-size:1.05rem; letter-spacing:-.03em; }.text-action { display:inline-flex; align-items:center; gap:.35rem; color:var(--acid); font-size:.72rem; font-weight:700; text-decoration:none; }.text-action svg { width:.9rem; height:.9rem; fill:none; stroke:currentColor; stroke-linecap:round; stroke-linejoin:round; stroke-width:1.6; transition:transform .16s ease; }.text-action:hover svg { transform:translateX(.15rem); }.text-action:focus-visible,.ai-brief a:focus-visible,.attention-row:focus-visible { outline:3px solid rgb(23 105 224 / 18%); outline-offset:3px; }.attention-list { border-top:1px solid var(--line); }.attention-row { display:flex; width:100%; align-items:center; justify-content:space-between; gap:1rem; padding:1rem 1.2rem; border:0; border-bottom:1px solid var(--line); background:#fff; text-align:left; transition:background .16s ease; }.attention-row:hover { background:#f8fbff; }.ticket-main { min-width:0; }.ticket-code { display:block; color:var(--acid); font-size:.67rem; font-weight:700; }.ticket-main strong { display:block; overflow:hidden; margin:.22rem 0; color:var(--bone); font-size:.8rem; text-overflow:ellipsis; white-space:nowrap; }.ticket-main small { color:var(--dim); font-size:.7rem; }.ticket-tags { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:.4rem; }.ai-brief { display:flex; justify-content:space-between; gap:1rem; padding:1.35rem; border:1px solid rgb(8 126 164 / 20%); border-radius:14px; background:linear-gradient(145deg,#e8f8fc,#f8fcff); color:#244861; }.ai-brief h2 { margin:0 0 .7rem; font-family:"Manrope",sans-serif; font-size:1.3rem; letter-spacing:-.035em; }.ai-brief p { max-width:25rem; margin:0; color:#527187; font-size:.78rem; line-height:1.6; }.ai-brief a { display:inline-block; margin-top:1.15rem; color:var(--cyan); font-size:.74rem; font-weight:700; text-decoration:none; text-underline-offset:.2rem; }.ai-brief a:hover { text-decoration:underline; }.ai-marker { width:2rem; height:2rem; flex:0 0 2rem; fill:none; stroke:var(--cyan); stroke-linecap:round; stroke-linejoin:round; stroke-width:1.4; }.analytics { display:grid; grid-template-columns:1.45fr 1fr; gap:1rem; margin-top:1rem; }.chart-panel,.category-panel { min-height:270px; }.bar-chart { display:flex; height:190px; align-items:flex-end; gap:.7rem; padding:0 1.2rem 1.2rem; }.bar { display:grid; flex:1; height:100%; grid-template-rows:auto 1fr auto; align-items:end; gap:.35rem; text-align:center; }.bar-value,.bar small { color:var(--dim); font-size:.66rem; }.track { display:flex; height:100%; align-items:flex-end; border-radius:7px 7px 0 0; background:#f0f4fa; overflow:hidden; }.track i { display:block; width:100%; border-radius:7px 7px 0 0; background:linear-gradient(180deg,#5aa0f8,#1769e0); }.category-panel { padding:1.15rem 1.2rem; }.category-list { display:grid; gap:.9rem; margin-top:1.25rem; }.category-list > div { display:grid; grid-template-columns:minmax(70px,1fr) 2fr 1.5rem; align-items:center; gap:.65rem; color:var(--dim); font-size:.72rem; }.category-line { height:8px; overflow:hidden; border-radius:99px; background:#eef3fa; }.category-line i { display:block; height:100%; border-radius:99px; background:#28a5ca; }.category-list b { color:var(--bone); text-align:right; }.agents { margin-top:1rem; overflow:hidden; }.table-scroll { overflow-x:auto; } table { width:100%; min-width:640px; border-collapse:collapse; font-size:.76rem; } th { padding:.75rem 1.2rem; border-top:1px solid var(--line); border-bottom:1px solid var(--line); color:var(--dim); font-size:.67rem; text-align:left; } td { padding:.9rem 1.2rem; border-bottom:1px solid #eef2f7; color:var(--dim); } td strong { color:var(--bone); }.progress { width:8rem; height:7px; overflow:hidden; border-radius:99px; background:#eef3fa; }.progress i { display:block; height:100%; border-radius:99px; background:var(--acid); }.empty-copy { color:var(--dim); font-size:.8rem; }
  @keyframes spin { to { transform:rotate(360deg); } }
  @media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}} @media(max-width:760px){.section-header,.work-grid,.analytics{grid-template-columns:1fr; align-items:flex-start;}.section-header{flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr)}.attention-row{align-items:flex-start;flex-direction:column}.ticket-tags{justify-content:flex-start}.period{width:100%}.ai-marker{width:1.6rem;height:1.6rem;flex-basis:1.6rem}} @media(max-width:440px){.metrics{grid-template-columns:1fr}.bar-chart{gap:.35rem;padding-left:.75rem;padding-right:.75rem}.bar small{font-size:.58rem}}
</style>
